#!/usr/bin/env python3
"""Build the static, fail-closed research site from recorded audit evidence."""
from __future__ import annotations
import html
import json
from pathlib import Path
import shutil

ROOT = Path(__file__).resolve().parents[1]
DOCS = ROOT / 'docs'
H = html.escape

LOGO = '''<svg width="20" height="20" viewBox="0 0 20 20" fill="none" aria-hidden="true"><path d="M2 14.5 7 9.4l3.1 2.5L16.8 5M2 18l5.3-5.4 3.2 2.4L17.8 8" stroke="#c8e4d0" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round"/></svg>'''
ICON_ARROW = '<span aria-hidden="true">↗</span>'


def header(active: str) -> str:
    links = [('overview','index.html','Overview'),('review','index.html#portfolio','Nine-site review'),
             ('research','research.html','Research'),('guide','executive-summary.html','Submission guide')]
    nav = ''.join(f'<a href="{url}"' + (' aria-current="page"' if active == key else '') + f'>{label}</a>'
                  for key,url,label in links)
    return f'''<header class="topbar"><div class="shell nav"><a class="brand" href="index.html" aria-label="GEMS Research home"><span class="brand-icon">{LOGO}</span><span class="brand-text">GEMS Research<small>Fault discovery workspace</small></span></a><nav class="nav-links" aria-label="Main navigation">{nav}<a class="nav-link-strong" href="https://www.drivendata.org/competitions/306/competition-doe-gems/leaderboard/">Official leaderboard ↗</a></nav></div></header>'''


def footer() -> str:
    return '''<footer class="footer"><div class="shell footer-inner"><div><strong>GEMS Research</strong> · Evidence before submission<br><span>Independent research workspace. Not affiliated with DrivenData or the USGS.</span></div><div><a href="data/run-card.json">Run card</a> &nbsp;·&nbsp; <a href="data/portfolio-audit.json">Audit data</a> &nbsp;·&nbsp; <a href="https://github.com/wingbangboozle1-lang/WBGGEMSDOE2">Repository ↗</a></div></div></footer>'''


def page(title: str, body: str, active: str, description: str) -> str:
    return f'''<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="description" content="{H(description,quote=True)}"><meta name="color-scheme" content="light"><title>{H(title)} · GEMS Research</title><link rel="stylesheet" href="assets/style.css"><script src="assets/app.js" defer></script></head><body>{header(active)}{body}{footer()}</body></html>\n'''


def portfolio_rows(report: dict) -> str:
    rows = sorted(report['focus_sites'], key=lambda r: float(r['claimed_score']), reverse=True)
    out = []
    for row in rows:
        site, peer = H(row['site']), H(row['max_overlap_peer'])
        percent = f"{row['max_overlap'] * 100:.1f}%"
        name = H(Path(row['path']).name)
        href = H(row['link'], quote=True)
        out.append(f'''<tr data-site="{site.lower()}"><td><span class="site-name">{site}</span><span class="minor">Pinned historic reference</span></td><td><a class="file-link" href="{href}">{name} ↗</a><span class="minor">Research only · do not upload</span></td><td><span class="score">{H(row['claimed_score'])}</span><span class="minor">User-reported · unverified</span></td><td><span class="badge gray">Unknown</span><span class="minor">No calibrated estimate</span></td><td><span class="badge red">No</span><span class="minor">{percent} near {peer}</span></td><td><span class="badge gray">Do not submit</span><span class="minor">Previously reported</span></td></tr>''')
    return '\n'.join(out)


def current_rows(report: dict) -> str:
    out = []
    for row in report['results']:
        site, label = H(row['site']), H(row['label'])
        name = H(Path(row['path']).name)
        href = H(row['reference_download'], quote=True)
        lattice = row['overlap']['lattice']['fraction'] * 100
        dense = row['overlap']['dense_probability']['fraction'] * 100
        out.append(f'''<tr><td><span class="site-name">{site} · {label}</span><span class="minor">External research artifact</span></td><td><a class="file-link" href="{href}">{name} ↗</a><span class="minor">SHA-256 verified · research only</span></td><td><span class="badge red">{lattice:.2f}%</span><span class="minor">against lattice</span></td><td><span class="badge red">{dense:.0f}%</span><span class="minor">against dense surface</span></td><td><span class="badge gray">Do not submit</span><span class="minor">Both literal witnesses fail</span></td></tr>''')
    return '\n'.join(out)


def build():
    report = json.loads((ROOT / 'evidence/portfolio_audit.json').read_text())
    current = json.loads((ROOT / 'evidence/current_candidates_audit.json').read_text())
    card = json.loads((ROOT / 'evidence/run_card.json').read_text())
    if card['verdict'] != 'negative' or card['ok_to_submit'] or card['raster_sha256'] is not None:
        raise ValueError('site status must be rebuilt from an independently verified gate decision')
    if not report['dense_surface_witness']['uncovered_footprint_pixels_within_3px'] == 0:
        raise ValueError('universal stop witness no longer established')
    if len(report['focus_sites']) != 9:
        raise ValueError('incomplete nine-site audit')
    (DOCS / 'data').mkdir(parents=True, exist_ok=True)
    if len(current['results']) != 3 or any(
        r['ok_to_submit'] or not r['literal_duplicate_witnesses'] or not all(r['local_format_checks'].values())
        for r in current['results']
    ):
        raise ValueError('current research wording must be rebuilt from saved-byte gates')
    for src, dst in [('portfolio_audit.json','portfolio-audit.json'),('run_card.json','run-card.json'),
                     ('shared_tool_checks.json','shared-tool-checks.json'),
                     ('current_candidates_audit.json','current-candidates-audit.json')]:
        shutil.copyfile(ROOT / 'evidence' / src, DOCS / 'data' / dst)
    feed = DOCS / 'data/feed.json'
    if not feed.exists():
        shutil.copyfile(ROOT / 'data/leaderboard_snapshot.json', feed)
    snapshot = json.loads(feed.read_text())
    if 'top_score' not in snapshot:
        raise ValueError('feed is missing its last observed score')
    top_score = H(str(snapshot['top_score']))
    observed = H(snapshot.get('observed_at_utc') or snapshot.get('observed_date_utc') or 'date unavailable')
    audited = H(report['audited_at_utc'][:10])
    witness = report['dense_surface_witness']
    positives = f"{witness['finite_positive_footprint_pixels']:,}"
    rows = portfolio_rows(report)
    current_research_rows = current_rows(current)
    current_table = f'''<div class="table-wrap"><div class="scroll-x"><table><caption class="sr-only">Newer external research artifacts and their duplicate-witness checks</caption><thead><tr><th>Research file</th><th>Pinned download</th><th>3-px lattice overlap</th><th>3-px dense overlap</th><th>Decision</th></tr></thead><tbody>{current_research_rows}</tbody></table></div><div class="table-foot">Our saved-byte check, using the mirrored footprint. Full-grid format checks passed locally, not at the organizer portal. Pre-placement surfaces and independent holdouts were not replayed. <a href="data/current-candidates-audit.json">Download exact audit ↗</a></div></div>'''
    hero_svg = '''<svg viewBox="0 0 400 260" fill="none" aria-hidden="true"><rect x="33" y="19" width="326" height="219" rx="18" fill="#F8FBF6" stroke="#D8E6D6"/><path d="M33 73h326M33 127h326M33 181h326M98 19v219M163 19v219M228 19v219M293 19v219" stroke="#E8EFE5"/><path d="M41 184c25-8 34-26 51-31 20-7 25 10 45 4 20-5 27-32 48-39 24-9 32 8 51 2 21-7 27-29 45-35 27-9 37 5 69-10" stroke="#B8D4BD" stroke-width="2"/><path d="M42 204c23-7 40-23 57-28 21-6 27 8 45 3 20-5 26-29 49-36 21-7 30 8 49 1 22-7 29-28 47-33 22-7 40 3 61-5" stroke="#D5E7D5" stroke-width="2"/><path d="M48 145c21-8 32-28 51-33 19-5 26 10 45 4 19-5 27-29 48-35 23-8 31 8 51 2 20-7 28-29 46-34 25-7 38 4 61-3" stroke="#D1E5D2" stroke-width="2"/><path d="M89 193 150 149 203 148 259 93 316 75" stroke="#315F4C" stroke-width="2.5" stroke-linecap="round" stroke-dasharray="3 7"/><circle cx="89" cy="193" r="5" fill="#D17B51"/><circle cx="150" cy="149" r="5" fill="#D17B51"/><circle cx="203" cy="148" r="5" fill="#D17B51"/><circle cx="259" cy="93" r="5" fill="#D17B51"/><circle cx="316" cy="75" r="5" fill="#D17B51"/><rect x="235" y="176" width="103" height="37" rx="9" fill="white" stroke="#DCE9DC"/><circle cx="249" cy="190" r="3" fill="#D17B51"/><path d="M258 189h64M247 199h54" stroke="#B7CDBC" stroke-width="3" stroke-linecap="round"/></svg>'''
    body = f'''<main class="main"><div class="shell"><div class="crumb"><span>Research workspace</span><span>Overview</span></div>
<section class="hero"><div class="hero-copy"><div class="eyebrow">DOE GEMS prize · decision brief</div><h1>Evidence before<br>the next submission.</h1><p>A clear view of the strongest reported results, what the data actually show, and whether a new file is ready to compete.</p><div class="hero-buttons"><a class="button" href="#portfolio">Explore the nine sites <span aria-hidden="true">→</span></a><a class="button secondary" href="executive-summary.html">Submission guide <span aria-hidden="true">↗</span></a></div></div><div class="hero-art">{hero_svg}</div></section>
<section class="stop-card" aria-labelledby="stop-title"><div class="stop-icon" aria-hidden="true">!</div><div class="stop-main"><div class="stop-title" id="stop-title">No new TIFF is approved for submission.</div><div class="stop-copy">The literal uniqueness rule is mathematically blocked by a registered dense raster. No TIFF was generated and no competition slot was used.</div></div><span class="status-badge">Automated stop</span></section>
<section class="metrics" aria-label="At a glance"><article class="metric"><div class="metric-label">Best of the nine · reported</div><div class="metric-value">0.2778</div><div class="metric-sub">GEMSDOE32 · user-reported, not verified</div></article><article class="metric"><div class="metric-label">Public leaderboard · official snapshot</div><div class="metric-value" data-feed-score>{top_score}</div><div class="metric-sub"><a href="https://www.drivendata.org/competitions/306/competition-doe-gems/leaderboard/">View organizer page ↗</a> · <span data-feed-date>{observed}</span></div></article><article class="metric"><div class="metric-label">New submission status</div><div class="metric-value text">Not ready</div><div class="metric-sub">No validated submission download</div></article><article class="metric"><div class="metric-label">Experiments / slots</div><div class="metric-value">0 / 0</div><div class="metric-sub">Stopped before placement</div></article></section>
<section class="section" id="portfolio"><div class="section-head"><div><div class="section-kicker">The comparison</div><h2>Nine sites. One evidence standard.</h2><p>Reference files are linked for research. The best reported historical score is not a new submission.</p></div><a class="text-link" href="data/portfolio-audit.json">Download audit data ↗</a></div><div class="table-wrap"><div class="table-tools"><div><strong>Historical best by focus site</strong><small>Reported scores lack organizer receipts · audited {audited} UTC</small></div><label><span class="hidden">Filter by site name</span><input class="search" id="site-search" type="search" placeholder="Find a site…" aria-label="Filter by site name"></label></div><div class="scroll-x"><table><caption class="sr-only">Historical research files and evidence for the nine focus sites</caption><thead><tr><th>Focus site</th><th>File · research only</th><th>Reported score</th><th>Estimated score</th><th>Unique vs other 8?</th><th>Decision</th></tr></thead><tbody id="site-rows">{rows}</tbody></table></div><div class="table-foot">Uniqueness is measured directionally as the fraction of each raster's positive cells within 3 pixels of another listed best. Pre-placement surfaces and the full global registry were not audited. Sites disagree on the GEMSDOE28/31 score-to-file mapping; the user-supplied mapping is shown as unverified. <a href="executive-summary.html#reading">Read what this means →</a></div></div></section>
<section class="section" id="current-research"><div class="section-head"><div><div class="section-kicker">Newer research files</div><h2>Format is not approval.</h2><p>Three external files have locally valid grids and ranges but fail the requested literal overlap rule. These are not new files from our run.</p></div><a class="text-link" href="data/current-candidates-audit.json">Download exact audit ↗</a></div>{current_table}</section>
<section class="section" id="evidence"><div class="section-head"><div><div class="section-kicker">What we learned</div><h2>A strong result, carefully explained.</h2><p>The raster relationship is measurable; the cause of a hidden-test score is not.</p></div><a class="text-link" href="research.html">Read the research notes ↗</a></div><div class="grid-2"><article class="card"><h3>Why the reported leader stands out</h3><div class="fact-list"><div class="fact"><span class="fact-num">01</span><div><b>The lineage is exact.</b><p>GEMSDOE32 B2 equals the GEMSDOE25 D2.8 dots after removing 6,436 dots within 2 pixels of the mirrored fault catalogue.</p></div></div><div class="fact"><span class="fact-num">02</span><div><b>The metric rewards useful coverage.</b><p>A 300 m triangular kernel gives nearby predictions partial credit; thinning can reduce false-positive mass while retaining some coverage.</p></div></div><div class="fact"><span class="fact-num">03</span><div><b>Cause is still uncertain.</b><p>The hidden labels and submission receipts are unavailable. The reported score and the reason for it cannot be independently confirmed.</p></div></div></div></article><article class="card witness"><div class="section-kicker">Registry stop witness</div><div class="witness-head"><div><h3>100% overlap,<br>by construction.</h3><p>A registered continuous probability surface is positive across every mirror-derived footprint cell. The shared literal gate treats every positive cell as support.</p></div></div><div class="bar" aria-hidden="true"><span></span></div><div class="bar-caption"><span>{positives} / {positives} footprint cells positive</span><strong>100%</strong></div><p>Any nonempty dot set therefore fails the literal 70% limit. This is a rule conflict, <strong>not proof of scientific copying</strong>.</p><p><a href="data/shared-tool-checks.json">See shared-template certificate ↗</a></p></article></div></section>
<section class="section"><div class="section-head"><div><div class="section-kicker">Validation pipeline</div><h2>How a file earns a green light.</h2><p>Format alone is never a submission decision.</p></div><a class="text-link" href="executive-summary.html">See the full guide ↗</a></div><div class="steps"><article class="step"><div class="step-index">01 / INPUTS</div><h3>Check provenance</h3><p>Pinned public mirrors restored; organizer identity remains unverified.</p><span class="badge gray">Partial</span></article><article class="step"><div class="step-index">02 / NOVELTY</div><h3>Compare registry</h3><p>Literal support overlap is impossible to pass for a nonempty raster.</p><span class="badge red">Blocked</span></article><article class="step"><div class="step-index">03 / SCIENCE</div><h3>Test on holdouts</h3><p>No feature canary or fold-local holdout was run after the stop.</p><span class="badge gray">Not run</span></article><article class="step"><div class="step-index">04 / OUTPUT</div><h3>Validate saved bytes</h3><p>No new TIFF exists, so no candidate format validation is claimed.</p><span class="badge gray">Not run</span></article></div></section>
<section class="section" id="sources"><div class="section-head"><div><div class="section-kicker">Primary sources</div><h2>Follow the evidence.</h2><p>Official competition and public-data sources for independent review.</p></div></div><div class="sources"><a class="source" href="https://www.drivendata.org/competitions/306/competition-doe-gems/page/967/"><span><b>Problem & metric</b><small>DrivenData · official challenge</small></span><span class="arrow">↗</span></a><a class="source" href="https://www.drivendata.org/competitions/306/competition-doe-gems/leaderboard/"><span><b>Public leaderboard</b><small>DrivenData · live standings</small></span><span class="arrow">↗</span></a><a class="source" href="https://community.drivendata.org/t/scoring-clarification-are-known-usgs-ingenious-faults-masked-when-scoring-and-are-they-in-the-final-round-label-set/11516/2"><span><b>Known-fault masking</b><small>DrivenData staff clarification</small></span><span class="arrow">↗</span></a><a class="source" href="https://www.usgs.gov/data/geodawn-airborne-magnetic-and-radiometric-surveys-northwestern-great-basin-nevada-and"><span><b>GeoDAWN survey</b><small>USGS · geophysical data release</small></span><span class="arrow">↗</span></a><a class="source" href="https://gdr.openei.org/submissions/1391"><span><b>INGENIOUS data</b><small>Geothermal Data Repository</small></span><span class="arrow">↗</span></a><a class="source" href="https://github.com/drivendataorg/gems-prize-reference-solution"><span><b>Reference solution</b><small>DrivenData · official starter</small></span><span class="arrow">↗</span></a></div><p class="disclaimer">Leaderboard feed: <span data-feed-status>snapshot</span>. A leaderboard observation is not a receipt for a specific file. <a href="data/feed.json">Feed metadata</a><br><span data-source-status>Focus-site source freshness not checked; comparisons remain pinned to the recorded audit.</span></p></section></div></main>'''
    (DOCS/'index.html').write_text(page('Overview', body, 'overview', 'Evidence-led GEMS competition research and submission readiness.'), encoding='utf8')

    guide = f'''<main class="main"><div class="shell"><div class="crumb"><span>Research workspace</span><span>Submission guide</span></div><div class="page-head"><div class="eyebrow">Executive summary</div><h1>Exactly what to submit.<br>And when not to.</h1><p>A practical guide to the competition file, the automated gates, and the evidence behind the current stop.</p></div><div class="callout"><strong>Current decision: DO NOT SUBMIT.</strong> There is no newly generated, validated TIFF. The historical downloads are references only, not approved replacements.</div>
<div class="prose"><section><div class="section-kicker">01 / Current state</div><h2>There is no cleared file today.</h2><p>Our literal registry check has a mathematical blocker: a registered continuous prediction raster is positive across the entire mirror-derived footprint, so the shared positive-support definition makes every nonempty prediction overlap it by 100%. The rule says stop above 70%. This indicates an ambiguous comparison policy, not scientific identity; no exclusion has been quietly applied. See the <a href="data/shared-tool-checks.json">shared certificate</a> and <a href="data/run-card.json">negative run card</a>.</p><p>The highest user-reported result among the nine sites is GEMSDOE32 H33-B2 at <strong>0.2778</strong>, but no organizer receipt tying that score to a specific file was available. The <a href="index.html#portfolio">nine-site table</a> links historical files for research only. No prospective leaderboard score can be estimated reliably.</p></section>
<section id="reading"><div class="section-kicker">02 / Reading the table</div><h2>Reported is not confirmed.</h2><p>“Reported score” means supplied by the user and found in the focus-site research, not authenticated from a submission-page receipt. “Estimated score: unknown” means no defensible calibration from catalogue hide-and-recover to the organizer's hidden faults. “Unique: no” means the listed raster has more than 70% of its positive pixels within 3 pixels of another of the eight historical bests. That test does not establish pre-placement surface correlation or exhaust every previous submission. All files are marked <strong>do not submit</strong>.</p><div class="table-wrap"><div class="scroll-x"><table><caption class="sr-only">Historical nine-site reference files, scores, estimates and uniqueness</caption><thead><tr><th>Focus site</th><th>File · research only</th><th>Reported score</th><th>Estimated score</th><th>Unique vs other 8?</th><th>Decision</th></tr></thead><tbody>{rows}</tbody></table></div><div class="table-foot">Pinned references only. Site reports disagree on the GEMSDOE28/31 score-to-file mapping; no historical file is approved for resubmission.</div></div></section>
<section><div class="section-kicker">Newer external research files</div><h2>Local format checks do not override the stop.</h2><p>These existing files from other sites are provided for research only. Our saved-byte audit finds both registered witnesses above the 70% limit; we did not rerun their scientific holdouts or pre-placement correlations.</p>{current_table}</section>
<section><div class="section-kicker">03 / If a future candidate passes</div><h2>Submission checklist</h2><div class="steps-list"><article><span class="step-no">01</span><div><h3>Check the automated decision first.</h3><p>Obtain an authorized interpretation of the registry rule and a named method lane. Require visible-only feature construction, leakage canaries, a paired spatial holdout win over the strongest comparable baseline, and complete uniqueness and format checks. Promotion is a separate selector step.</p></div></article><article><span class="step-no">02</span><div><h3>Download only the newly approved file.</h3><p>When available, download the single-band GeoTIFF or a ZIP containing exactly one GeoTIFF. Confirm the recorded SHA-256 and unique name. Today there is no such download.</p></div></article><article><span class="step-no">03</span><div><h3>Verify format against the organizer's sample.</h3><p>The official requirements include float32 probabilities in [0,1], EPSG:32611, 100 m pixels, matching bounds/transform/shape, and null or NaN outside bounds. The shared writer rejects invalid values instead of silently clipping them. A locally all-finite output is a precaution, not evidence of organizer acceptance.</p></div></article><article><span class="step-no">04</span><div><h3>Use the DrivenData submission form.</h3><p>After signing in and checking the actual weekly quota on the submission page, choose “Make new submission,” attach the approved file, add its short identifying note, and submit. Save the organizer receipt and score. No upload is made by this site.</p></div></article></div></section>
<section><div class="section-kicker">04 / Troubleshooting</div><h2>About the [0,1] error.</h2><p>Every prediction inside the valid footprint must be finite and between zero and one. Some historical files contain outside-footprint NaNs; those may be relevant to a range error, but the rejected file and portal validator are unavailable, so the actual cause has not been established. Do not silently clip bad predictions. Use the shared, strict saved-byte validator, compare the exact organizer template, and retain the portal's receipt.</p><p>Consult the <a href="https://www.drivendata.org/competitions/306/competition-doe-gems/page/967/#submission-format">official format</a>, <a href="https://www.drivendata.org/competitions/306/competition-doe-gems/rules/">rules</a>, and <a href="https://www.drivendata.org/competitions/306/competition-doe-gems/data/">data page</a> (login required). The organizer may update their rules or validator.</p></section></div></div></main>'''
    (DOCS/'executive-summary.html').write_text(page('Submission guide',guide,'guide','How to assess and submit a future GEMS GeoTIFF, and why no current file is approved.'),encoding='utf8')

    research = '''<main class="main"><div class="shell"><div class="crumb"><span>Research workspace</span><span>Research</span></div><div class="page-head"><div class="eyebrow">Science &amp; provenance</div><h1>Ideas worth testing.<br>Claims worth checking.</h1><p>The objective is to map previously unrecorded geological faults associated with geothermal resources—not to claim that a predicted pixel is a verified geothermal vent.</p></div><div class="callout"><strong>Research stopped before model construction.</strong> The prompt does not specify its promised single method lane, and the literal registry gate has a universal stop witness. No candidate, holdout score, confidence interval, or leaderboard forecast was fabricated.</div><div class="prose"><section><div class="section-kicker">Preliminary ranking · qualitative only</div><h2>Four physically grounded hypotheses.</h2><p>Expected value is a research judgment, not a score. Novelty is only relative to inspected work; it is not an exhaustive literature or concurrent-lane search.</p><div class="steps-list"><article><span class="step-no">01</span><div><h3>Radiometric contact shear offset · medium cost</h3><p>Compare along-strike shifts of potassium/thorium contacts on either side of coherent LiDAR scarps. An unmapped fault could displace a contact; terraces, roads, stratigraphic pinch-outs and survey artefacts can mimic it. This differs from simply matching parallel magnetic and topographic gradients.</p></div></article><article><span class="step-no">02</span><div><h3>Terrain / stratigraphy discordance · low–medium cost</h3><p>Test whether a coherent scarp cuts across a radiometric unit boundary. Streams, mines and missing data can also produce cross-cutting patterns.</p></div></article><article><span class="step-no">03</span><div><h3>Conductive-basement step · medium cost</h3><p>Combine a lateral conductive-base depth change with contrasting radiometry. Buried facies boundaries and inversion-resolution artefacts remain alternatives.</p></div></article><article><span class="step-no">04</span><div><h3>Paleothermal lineament intersections · high cost</h3><p>Test GDR sinter/tufa locations against intersecting persistent LiDAR lineaments with matched sampling-effort controls. Depositional and survey bias are potential mimics; spatial coverage has not been independently checked.</p></div></article></div></section><section><div class="section-kicker">Verified input caveat</div><h2>Trace the data, not just the hash.</h2><p>The official <a href="https://www.usgs.gov/data/geodawn-airborne-magnetic-and-radiometric-surveys-northwestern-great-basin-nevada-and">USGS GeoDAWN</a> release describes airborne magnetic and radiometric data with coordinated lidar; it is marked CC0. The <a href="https://gdr.openei.org/submissions/1391">GDR INGENIOUS record</a> includes paleogeothermal, fault, temperature and other layers under CC BY 4.0. The aligned layers and template used in the audit are owner-hosted mirrors: their hashes are pinned, but their organizer origin was not independently authenticated.</p></section><section><div class="section-kicker">Protocol notes</div><h2>Open issues, not hidden assumptions.</h2><ul><li>The mirror sample's positive support equals the fault-label support, whereas the official description calls the sample fault-absence; only its grid and finite footprint were used.</li><li>Two GEMSDOE32 command-line wrappers binarize soft predictions. We use the pinned shared GEMSDOE57 evaluator/writer for fixtures and report the upstream issue; no private fork was made.</li><li>The official public leaderboard and historical user reports are different evidence classes. Scores from different holdout protocols are not directly comparable.</li><li>A successful local format check cannot guarantee portal acceptance or a high private score.</li></ul><p><a href="https://github.com/wingbangboozle1-lang/WBGGEMSDOE2/blob/main/research/preregistration.md">Read the full preregistration ↗</a> · <a href="https://github.com/wingbangboozle1-lang/WBGGEMSDOE2/blob/main/research/findings.md">Read the findings and irregularities ↗</a></p></section></div></div></main>'''
    (DOCS/'research.html').write_text(page('Research',research,'research','Ranked geological hypotheses and provenance limitations.'),encoding='utf8')
    print('Built docs/index.html, executive-summary.html, research.html and evidence copies')


